import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, color, mix, smoothstep, vec2, length, float, fract } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Box3, DirectionalLight } = ctx.THREE;

  const root = new Group();
  const disposables = [];
  const primHandles = [];
  const tweens = [];

  // ---------- SHARED STAGE COLOR (world-space, reused by backdrop AND edge masks
  // so the fade dissolves into the true stage gradient instead of a flat black rect) ----------
  function stageColor(wx, wy) {
    // vertical lift: #0b0b10 -> #16161d bottom to top
    const ny = wy.div(12.0).add(0.5);
    let base = mix(color('#0b0b10'), color('#16161d'), ny.mul(0.85));
    // engineered elliptical glow behind the instrument rail
    const glow = smoothstep(1.0, 0.0, length(vec2(wx.div(7.0), wy.div(2.2))));
    base = mix(base, color('#23232b'), glow.mul(0.9));
    // hairline scanlines on the 0.25-unit rhythm (blueprint instrumentation)
    const line = smoothstep(0.0, 0.06, fract(wy.mul(4.0))).oneMinus();
    base = base.add(color('#e8ecf2').mul(line).mul(0.02).mul(glow.mul(0.7).add(0.3)));
    // corner vignette back down to background
    const vd = length(vec2(wx.div(10.0), wy.div(6.0)));
    base = base.mul(float(1.0).sub(smoothstep(0.75, 1.15, vd).mul(0.35)));
    return base;
  }

  // ---------- STAGE BACKDROP (fills entire frame at z=-2.5, no black surround) ----------
  const bgGeo = new PlaneGeometry(22, 12);
  const bgMat = new MeshBasicNodeMaterial();
  {
    const wx = uv().x.sub(0.5).mul(22.0);
    const wy = uv().y.sub(0.5).mul(12.0);
    bgMat.colorNode = stageColor(wx, wy);
  }
  const backdrop = new Mesh(bgGeo, bgMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(bgGeo, bgMat);

  // ---------- MID-DEPTH RULER TICK ROWS (instrumentation texture at z=-1.8) ----------
  const tickRowGeoS = new PlaneGeometry(0.006, 0.05);
  const tickRowGeoT = new PlaneGeometry(0.006, 0.1);
  const tickRowMat = new MeshBasicNodeMaterial();
  tickRowMat.color.set('#23232b');
  disposables.push(tickRowGeoS, tickRowGeoT, tickRowMat);
  for (const ry of [1.5, -1.5]) {
    for (let i = 0; i <= 28; i++) {
      const x = -3.5 + i * 0.25;
      const tall = i % 4 === 0;
      const m = new Mesh(tall ? tickRowGeoT : tickRowGeoS, tickRowMat);
      m.position.set(x, ry, -1.8);
      root.add(m);
    }
  }

  // ---------- RAIL PLANE 7.0 x 0.35 ----------
  const railGeo = new PlaneGeometry(7.0, 0.35);
  const railMat = new MeshStandardNodeMaterial();
  railMat.color.set('#111117');
  railMat.roughness = 0.6;
  railMat.metalness = 0.2;
  const rail = new Mesh(railGeo, railMat);
  rail.position.set(0, 0, 0);
  root.add(rail);
  disposables.push(railGeo, railMat);

  // ---------- HAIRLINES top/bottom ----------
  const hairGeo = new PlaneGeometry(7.0, 0.006);
  const hairMat = new MeshBasicNodeMaterial();
  hairMat.color.set('#23232b');
  const hairTop = new Mesh(hairGeo, hairMat);
  hairTop.position.set(0, 0.172, 0.005);
  const hairBot = new Mesh(hairGeo, hairMat);
  hairBot.position.set(0, -0.172, 0.005);
  root.add(hairTop, hairBot);
  disposables.push(hairGeo, hairMat);

  // ---------- ACCENT UNDER-GLOW beneath the rail (instrument light leak) ----------
  const glowGeo = new PlaneGeometry(7.2, 0.1);
  const glowMat = new MeshBasicNodeMaterial();
  glowMat.colorNode = color('#ff2a38');
  glowMat.opacityNode = smoothstep(0.0, 0.2, uv().x)
    .mul(smoothstep(1.0, 0.8, uv().x))
    .mul(smoothstep(0.0, 0.5, uv().y).mul(smoothstep(1.0, 0.5, uv().y)))
    .mul(0.22);
  glowMat.transparent = true;
  glowMat.depthWrite = false;
  const underGlow = new Mesh(glowGeo, glowMat);
  underGlow.position.set(0, -0.235, -0.1);
  root.add(underGlow);
  disposables.push(glowGeo, glowMat);

  // ---------- Node-local rim light so mono digits get a crisp top edge ----------
  const rim = new DirectionalLight('#e8ecf2', 0.7);
  rim.position.set(0, 2.5, 2.0);
  root.add(rim);

  // ---------- TICKER STRIP ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const strings = items
    .map((it) => (typeof it === 'string' ? it : it.text))
    .filter((s) => typeof s === 'string' && s.length > 0);

  const tickGeo = new PlaneGeometry(0.02, 0.14);
  const tickMat = new MeshStandardNodeMaterial();
  tickMat.color.set('#ff2a38');
  tickMat.emissiveNode = color('#ff2a38').mul(1.5); // brightest element in frame
  tickMat.roughness = 0.5;
  tickMat.metalness = 0.0;
  disposables.push(tickGeo, tickMat);

  function buildStrip() {
    const g = new Group();
    let x = 0;
    for (const s of strings) {
      const t = ctx.fontAtlas.createText(s, {
        fontSize: 13,
        color: '#e8ecf2',
        align: 'left',
        letterSpacingPx: 0.78
      });
      const holder = new Group();
      holder.add(t);

      const box = new Box3().setFromObject(t);
      let w = s.length * 0.078; // fallback estimate
      if (isFinite(box.min.x) && box.max.x > box.min.x && box.max.y > box.min.y) {
        const bw = box.max.x - box.min.x;
        const bh = box.max.y - box.min.y;
        const k = 0.13 / bh; // normalize glyph height to 0.13 scene units
        t.scale.setScalar(k);
        t.position.set(-box.min.x * k, -((box.min.y + box.max.y) / 2) * k, 0);
        w = bw * k;
      }

      holder.position.set(x, 0, 0.02); // float above the rail
      g.add(holder);
      x += w + 0.5; // 2x base unit gap before tick

      const tick = new Mesh(tickGeo, tickMat);
      tick.position.set(x + 0.01, 0, 0.02);
      g.add(tick);
      x += 0.02 + 0.5; // tick width + 2x base unit gap after tick
    }
    return { group: g, length: Math.max(x, 0.001) };
  }

  const scroller = new Group();
  const anchor = new Group(); // pins strip origin at left edge of ribbon
  anchor.position.set(-3.5, 0, 0);
  anchor.add(scroller);
  root.add(anchor);

  const first = buildStrip();
  const stripLen = first.length;
  scroller.add(first.group);

  // duplicate strip for a seamless loop; ensure coverage of the full 7-unit rail at all times
  const copies = Math.max(2, Math.ceil(7.5 / stripLen) + 1);
  for (let i = 1; i < copies; i++) {
    const c = buildStrip();
    c.group.position.x = stripLen * i;
    scroller.add(c.group);
  }

  // constant velocity 0.4 units/s leftward, linear timing, zero visible seam
  const loop = gsap.to(scroller.position, {
    x: -stripLen,
    duration: stripLen / 0.4,
    ease: 'none',
    repeat: -1
  });
  tweens.push(loop);

  // ---------- EDGE FADE MASKS (0.6-unit ramps that dissolve into the STAGE gradient,
  // colored via the shared stageColor function with parallax compensation so no
  // rectangular black patch ever appears over the backdrop) ----------
  const maskW = 3.2;
  const maskH = 0.7;
  const fadeFrac = (maskW - 0.6) / maskW; // opaque until final 0.6 units
  const parallax = 12.5 / 9.95; // camera z=10, mask z~0.05 -> backdrop z=-2.5 ray scale

  function makeMask(side) {
    const cx = side * (2.9 + maskW / 2);
    const geo = new PlaneGeometry(maskW, maskH);
    const mat = new MeshBasicNodeMaterial();
    const wx = uv().x.sub(0.5).mul(maskW).add(cx).mul(parallax);
    const wy = uv().y.sub(0.5).mul(maskH).mul(parallax);
    mat.colorNode = stageColor(wx, wy);
    const ax = side < 0 ? uv().x : uv().x.oneMinus();
    mat.opacityNode = smoothstep(fadeFrac, 1.0, ax).oneMinus();
    mat.transparent = true;
    mat.depthWrite = false;
    const mesh = new Mesh(geo, mat);
    mesh.position.set(cx, 0, 0.05);
    mesh.renderOrder = 10;
    disposables.push(geo, mat);
    return mesh;
  }
  root.add(makeMask(-1), makeMask(1));

  // ---------- FOREGROUND ACCENT END-STOPS (third depth plane, z=+0.3) ----------
  const stopGeo = new PlaneGeometry(0.015, 0.22);
  const stopMat = new MeshStandardNodeMaterial();
  stopMat.color.set('#ff2a38');
  stopMat.emissiveNode = color('#ff2a38').mul(0.9); // graded below the ticker ticks
  stopMat.roughness = 0.5;
  stopMat.metalness = 0.0;
  disposables.push(stopGeo, stopMat);
  const stopL = new Mesh(stopGeo, stopMat);
  stopL.position.set(-3.62, 0, 0.3);
  const stopR = new Mesh(stopGeo, stopMat);
  stopR.position.set(3.62, 0, 0.3);
  root.add(stopL, stopR);

  // ---------- CINEMATIC PRIMITIVES (from config, never inlined) ----------
  for (const p of config.cinematicPrimitives ?? []) {
    const fn = ctx.primitives?.[p.name];
    if (fn) {
      const h = fn(root, p.params ?? {});
      if (h) primHandles.push(h);
    }
  }

  // ---------- HANDLERS / CLEANUP ----------
  root.userData.handlers = {};
  root.userData.cleanup = () => {
    for (const tw of tweens) tw.kill();
    for (const h of primHandles) {
      if (h && typeof h.cleanup === 'function') h.cleanup();
      if (h && h.timeline && typeof h.timeline.kill === 'function') h.timeline.kill();
    }
    root.traverse((obj) => {
      if (obj.geometry && !disposables.includes(obj.geometry)) obj.geometry.dispose?.();
      if (obj.material && !disposables.includes(obj.material)) {
        if (Array.isArray(obj.material)) obj.material.forEach((m) => m.dispose?.());
        else obj.material.dispose?.();
      }
    });
    for (const d of disposables) d.dispose?.();
  };

  return root;
}
